import{_ as t,c as r,o as a,ag as o}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Sock Puppet Accounts/Phase1 First Action","description":"","frontmatter":{"title":"Sock Puppet Accounts/Phase1 First Action"},"headers":[],"relativePath":"general/sock-puppet-accounts-phase1-first-action.md","filePath":"general/sock-puppet-accounts-phase1-first-action.md","lastUpdated":null}'),i={name:"general/sock-puppet-accounts-phase1-first-action.md"};function n(s,e,l,p,c,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="sock-puppet-accounts-phase1-first-action" tabindex="-1">Sock Puppet Accounts/Phase1 First Action <a class="header-anchor" href="#sock-puppet-accounts-phase1-first-action" aria-label="Permalink to &quot;Sock Puppet Accounts/Phase1 First Action&quot;">​</a></h1><h2 id="principle" tabindex="-1">Principle <a class="header-anchor" href="#principle" aria-label="Permalink to &quot;Principle&quot;">​</a></h2><p>Minimize your “attack surface” and be deliberate before taking any action. You cannot take this step back!</p><p>Return to <a href="/general/sock-puppet-accounts-creation.html">Puppet Creation Outline</a></p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="prep-your-gear" tabindex="-1">Prep your gear <a class="header-anchor" href="#prep-your-gear" aria-label="Permalink to &quot;Prep your gear&quot;">​</a></h3><p>Why is this in the “first action”? Because things you do <em>may</em> impact your sock. For instance, if you are setting up a VM, the mirror you download an ISO from might persist with artifacts in your machine. Or if you think you will have to interact with a target on SMS, there is a reasonable risk they may compromise your phone… is that IMEI previously associated with you?</p><ul><li><p><strong>Phone</strong>: This can be the trickiest part, especially for High-Risk socks. If building a low-risk sock, using an old phone with a new, pre-paid SIM may work. If high-risk, you might need a new device and use it in a location not associated with you (i.e., phone GPS and cell towers).</p></li><li><p>Some online services let you send an MFA code to an unassociated individual for a by-use fee. This is an option but introduces other risks.</p></li><li><p><strong>VPS</strong>: The first IP you use to create an account/touch a resource matters. Using a static VPS (either to host environments or just tunnel traffic) is the best way I have found to balance protection and usability. When it comes to the “high value” social media platforms, I have had no luck creating or using Sock with a public VPN (e.g., Nord, Proton, PIA)</p></li><li><p><strong>Isolate</strong>: You must isolate your sock’s environment from your own. There are several ways to do this. The solution you choose depends on your threat model.</p></li><li><p>separate browser profile</p></li><li><p>a different browser</p></li><li><p>another user account</p></li><li><p>a local VM</p></li><li><p>a remote VM or browser (e.g., kasm)</p></li><li><p><strong>Apps</strong>: Consider how you will load applications in your environment. Do you need to have already an account to get the required application (i.e., in iOS)</p></li><li><p><strong>Mobile Emulator</strong>: This can be very useful after getting started but hard to use for account setup</p></li></ul><p><em><strong>Remember what artifacts may come over from your setup!</strong></em> You can’t take things back once you start. # Resources</p><ul><li><p>Android Emulators</p></li><li><p><a href="/general/android-virtual-device.html">Studio Guide</a></p></li><li><p><a href="https://developer.android.com/studio" target="_blank" rel="noreferrer">Android Studio</a></p></li><li><p><a href="https://docs.blissos.org/installation/install-in-a-virtual-machine/" target="_blank" rel="noreferrer">BlissOS</a></p></li><li><p><a href="https://www.genymotion.com/" target="_blank" rel="noreferrer">GenyMotion</a></p></li><li><p><a href="https://andauth.co/BlueStacks" target="_blank" rel="noreferrer">BlueStacks</a></p></li><li><p><a href="https://www.android-x86.org/" target="_blank" rel="noreferrer">Android x86</a></p></li><li><p><a href="https://github.com/remote-android/redroid-doc" target="_blank" rel="noreferrer">Redroid</a> (works on Kasm)</p></li><li><p>VM Software</p></li><li><p><a href="https://www.vmware.com/" target="_blank" rel="noreferrer">VMware</a></p></li><li><p><a href="https://www.virtualbox.org/" target="_blank" rel="noreferrer">Oracle VM VirtualBox</a> (see for a guide)</p></li><li><p>[<a href="https://www.proxmox.com/en/" target="_blank" rel="noreferrer">https://www.proxmox.com/en/</a> Proxmox</p></li><li><p>Powerful open-source server solutions)</p></li><li><p><a href="https://www.kasmweb.com/" target="_blank" rel="noreferrer">Kasm Workspaces | The Container Streaming Platform</a></p></li><li><p><a href="https://exiftool.org/" target="_blank" rel="noreferrer">ExifTool by Phil Harvey</a></p></li><li><p><a href="/general/guide-to-password-managers.html">Managers</a></p></li><li><p><a href="https://keepassxc.org/" target="_blank" rel="noreferrer">KeePassXC</a> (password, 2FA, and key manager)</p></li><li><p><a href="https://bitwarden.com/" target="_blank" rel="noreferrer">Bitwarden</a></p></li></ul><p>[Required]</p><p>[Teaming]</p>',12)])])}const f=t(i,[["render",n]]);export{d as __pageData,f as default};
